typedef struct { int type, a, b; } Op;
typedef struct { int bit, ctx; } Sym;

static int ibits(int v, int k) {
    unsigned n = (unsigned)v + (1u << k);
    int l = 0;
    while (n) { l++; n >>= 1; }
    return 2*l-k-1;
}

static void add_sym(Sym **p, int *n, int *cap, int bit, int ctx) {
    if (*n == *cap) { *cap = *cap ? *cap*2 : 1024; *p = realloc(*p, *cap*sizeof(**p)); }
    (*p)[*n] = (Sym){bit,ctx}; (*n)++;
}

static void add_int(Sym **p, int *n, int *cap, int v, int k, int base) {
    unsigned x=(unsigned)v+(1u<<k), mask=1;
    int L=0; while (x>>L) L++;
    for (int i=0;i<L-k-1;i++) add_sym(p,n,cap,0,base*99+k+1+i);
    add_sym(p,n,cap,1,base*99+L);
    for (int i=L-2;i>=0;i--) add_sym(p,n,cap,(x>>i)&1,base*99);
