static void add_bits(Sym **p, int *n, int *cap, Op *ops, int nop) {
    add_int(p,n,cap,nop,9,0);
    for (int q=0;q<nop;q++) {
        Op o=ops[q];
        if (!o.type) {
            add_sym(p,n,cap,0,1);
            add_sym(p,n,cap,0,8);
            add_int(p,n,cap,o.a,4,9);
        } else {
            add_sym(p,n,cap,1,1);
            add_int(p,n,cap,o.a,5,2);
