    if (*n == *cap) { *cap=*cap?*cap*2:1024; *p=realloc(*p,*cap*sizeof(**p)); }
    (*p)[*n]=(Op){type,a,b}; (*n)++; return 0;
}

static int make_greedy(const unsigned char *s, int N, Op **out, int *nout) {
    Op *ops=NULL; int no=0, co=0;
    for (int pos=0; pos<N;) {
        int best=0, bestD=0;
        for (int d=1; d<=pos; d++) {
            int l=0;
            while (pos+l<N && s[pos+l]==s[pos-d+l]) l++;
